import{_ as p,a0 as l,w as d,s as r,I as s,x as a,a1 as e,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Fedora 中結合權能使用 Podman | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 中結合權能使用 Podman | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 中結合權能使用 Podman | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 中結合權能使用 Podman | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201116 Podman with capabilities on Fedora","title":"在 Fedora 中結合權能使用 Podman","tag":"202011","desc":""},"relativePath":"202011/20201116 Podman with capabilities on Fedora.md","filePath":"[post].md"}'),g={name:"202011/20201116 Podman with capabilities on Fedora.md"};function u(m,i,h,b,k,f){const t=l("Link");return d(),r("div",null,[i[31]||(i[31]=s("h1",{id:"在-fedora-中結合權能使用-podman",tabindex:"-1"},[a("在 Fedora 中結合權能使用 Podman "),s("a",{class:"header-anchor",href:"#在-fedora-中結合權能使用-podman","aria-label":"Permalink to “在 Fedora 中結合權能使用 Podman”"},"​")],-1)),i[32]||(i[32]=s("p",null,[s("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/10/podman-816x345.jpg",alt:""})],-1)),s("p",null,[i[2]||(i[2]=a("容器化是一項蓬勃發展的技術。在不久的將來，多達百分之七十五的全球組織可能會運行某種類型的容器化技術。由於廣泛使用的技術更容易成為黑客攻擊的目標，因此保護容器的安全就顯得尤為重要。本文將演示如何使用 POSIX ",-1)),s("ruby",null,[e(t,{href:"https://www.linuxjournal.com/magazine/making-root-unprivileged"},{default:n(()=>[...i[0]||(i[0]=[a("權能",-1)])]),_:1}),i[1]||(i[1]=s("rt",null,"Capability",-1))]),i[3]||(i[3]=a(" 來保護 Podman 容器的安全。Podman 是 RHEL8 中默認的容器管理工具。",-1))]),i[33]||(i[33]=s("h3",{id:"確定-podman-容器的權限模式",tabindex:"-1"},[a("確定 Podman 容器的權限模式 "),s("a",{class:"header-anchor",href:"#確定-podman-容器的權限模式","aria-label":"Permalink to “確定 Podman 容器的權限模式”"},"​")],-1)),s("p",null,[i[6]||(i[6]=a("容器以特權模式或無特權模式運行。在特權模式下，",-1)),e(t,{href:"https://linuxcontainers.org/lxc/security/#privileged-containers"},{default:n(()=>[...i[4]||(i[4]=[a("容器的 uid 0 被映射到宿主機的 uid 0",-1)])]),_:1}),i[7]||(i[7]=a("。對於某些情況，無特權的容器",-1)),e(t,{href:"https://github.com/containers/podman/blob/master/rootless.md"},{default:n(()=>[...i[5]||(i[5]=[a("缺乏對宿主機資源的充分訪問能力",-1)])]),_:1}),i[8]||(i[8]=a("。但不管其操作模式如何，包括",-1)),i[9]||(i[9]=s("ruby",null,[a("強制訪問控制"),s("rt",null,"Mandatory Access Control")],-1)),i[10]||(i[10]=a("（MAC：如 apparmor、SELinux 等）、seccomp 過濾器、刪除",-1)),i[11]||(i[11]=s("ruby",null,[a("權能"),s("rt",null,"Capability")],-1)),i[12]||(i[12]=a("、命名空間等在內的技術有助於確保容器的安全。",-1))]),i[34]||(i[34]=o(`<p>要從容器外部確定特權模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman inspect --format=&quot;{{.HostConfig.Privileged}}&quot; &lt;container id&gt;</span></span></code></pre></div><p>如果上面的命令返回 <code>true</code>，那麼容器在特權模式下運行。如果返回 <code>false</code>，那麼容器在非特權模式下運行。</p><p>要從容器內部確定特權模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip link add dummy0 type dummy</span></span></code></pre></div><p>如果該命令允許你創建一個接口，那麼你運行的是一個特權容器，否則你運行的是一個非特權容器。</p><h3 id="權能" tabindex="-1">權能 <a class="header-anchor" href="#權能" aria-label="Permalink to “權能”">​</a></h3><p>命名空間隔離了容器的進程，使其無法任意訪問宿主機的資源，也無法訪問在同一宿主機上運行的其他容器的資源。然而，在<strong>特權</strong>容器內的進程仍然可以做一些事情，如改變 IP 路由表、跟蹤任意進程和加載內核模組。<ruby>權能<rt>Capability</rt></ruby>允許人們對容器內的進程可以訪問或更改的資源施加更細微的限制，即使容器在特權模式下運行也一樣。權能還允許人們為無特權的容器分配它本來不會擁有的特權。</p><p>例如，如果要將 <code>NET_ADMIN</code> 功能添加到一個無特權的容器中，以便在容器內部創建一個網絡接口，你可以用下面的參數運行 <code>podman</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@vm1 ~]# podman run -it --cap-add=NET_ADMIN centos</span></span>
<span class="line"><span>[root@b27fea33ccf1 /]# ip link add dummy0 type dummy</span></span>
<span class="line"><span>[root@b27fea33ccf1 /]# ip link</span></span></code></pre></div><p>上面的命令演示了在一個無特權的容器中創建一個 <code>dummy0</code> 接口。如果沒有 <code>NET_ADMIN</code> 權能，非特權容器將無法創建接口。上面的命令演示瞭如何將一個權能授予一個無特權的容器。</p>`,11)),s("p",null,[i[14]||(i[14]=a("目前，大約有 ",-1)),e(t,{href:"https://man7.org/linux/man-pages/man7/capabilities.7.html"},{default:n(()=>[...i[13]||(i[13]=[a("39 種權能",-1)])]),_:1}),i[15]||(i[15]=a("可以被授予或拒絕。特權容器默認會被授予許多權能。建議從特權容器中刪除不需要的權能，以使其更加安全。",-1))]),i[35]||(i[35]=o(`<p>要從容器中刪除所有權能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -it -d --name mycontainer --cap-drop=all centos</span></span></code></pre></div><p>列出一個容器的權能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman exec -it 48f11d9fa512 capsh --print</span></span></code></pre></div><p>上述命令顯示沒有向容器授予任何權能。</p><p>請參考 <code>capabilities</code> 手冊頁以獲取完整的權能列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man capabilities</span></span></code></pre></div><p>可以使用 <code>capsh</code> 命令來列出目前擁有的權能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ capsh --print</span></span></code></pre></div><p>作為另一個例子，下面的命令演示瞭如何從容器中刪除 <code>NET_RAW</code> 權能。如果沒有 <code>NET_RAW</code> 權能，就不能從容器中 <code>ping</code> 互聯網上的服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -it --name mycontainer1 --cap-drop=net_raw centos</span></span>
<span class="line"><span>&gt;&gt;&gt; ping google.com (will output error, operation not permitted)</span></span></code></pre></div><p>最後一個例子，如果你的容器只需要 <code>SETUID</code> 和 <code>SETGID</code> 權能，你可以刪除所有權能，然後只重新添加這兩個權能來實現這樣的權限設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run -d --cap-drop=all --cap-add=setuid --cap-add=setgid fedora sleep 5 &gt; /dev/null; pscap | grep sleep</span></span></code></pre></div><p>上面的 <code>pscap</code> 命令會顯示容器被授予的權能。</p><p>我希望你喜歡這個關於如何使用權能來保護 Podman 容器的簡短探索。</p><p>謝謝！</p><hr>`,17)),s("p",null,[i[17]||(i[17]=a("via: ",-1)),e(t,{href:"https://fedoramagazine.org/podman-with-capabilities-on-fedora/"},{default:n(()=>[...i[16]||(i[16]=[a("https://fedoramagazine.org/podman-with-capabilities-on-fedora/",-1)])]),_:1})]),s("p",null,[i[22]||(i[22]=a("作者：",-1)),e(t,{href:"https://fedoramagazine.org/author/shiwanibiradar/"},{default:n(()=>[...i[18]||(i[18]=[a("shiwanibiradar",-1)])]),_:1}),i[23]||(i[23]=a(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[19]||(i[19]=[a("lujun9972",-1)])]),_:1}),i[24]||(i[24]=a(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:n(()=>[...i[20]||(i[20]=[a("geekpi",-1)])]),_:1}),i[25]||(i[25]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[21]||(i[21]=[a("wxy",-1)])]),_:1})]),s("p",null,[i[28]||(i[28]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[26]||(i[26]=[a("LCTT",-1)])]),_:1}),i[29]||(i[29]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...i[27]||(i[27]=[a("Linux中國",-1)])]),_:1}),i[30]||(i[30]=a(" 榮譽推出",-1))])])}const T=p(g,[["render",u]]);export{C as __pageData,T as default};
